// Watchlist: one Google News RSS query per theme or account.
// Edit this list to track your own accounts. No API key needed.
const watchlist = [
  { watch: "New security leader",     query: 'appoints CISO OR "chief information security officer" Belgium OR Netherlands' },
  { watch: "AI rollout in finance",   query: 'bank OR insurer "rolls out" AI assistants Europe' },
  { watch: "AI Act readiness",        query: '"AI Act" compliance bank OR insurer' },
  { watch: "Belgian scale-up funding",query: 'Belgian startup raises "Series A" OR "Series B"' },
  { watch: "AI governance hiring",    query: '"AI governance" lead OR head hiring Europe' },
  // Add accounts the same way, e.g.:
  // { watch: "Acme Bank", query: '"Acme Bank" AI OR CISO OR funding' },
];

return watchlist.map(w => ({
  json: {
    watch: w.watch,
    query: w.query,
    url: "https://news.google.com/rss/search?q=" + encodeURIComponent(w.query) + "&hl=en&gl=BE&ceid=BE:en",
  },
}));

// Classify each article into a trigger type and score it.
// score = trigger strength x recency decay (half-life 21 days).
const HALF_LIFE_DAYS = 21;
const MAX_AGE_DAYS = 90;

const TRIGGERS = [
  { type: "new_exec",      strength: 0.8,  re: /\b(appoint(s|ed)?|names?|hires?|joins? as|new)\b.*\b(CISO|CIO|CTO|CDO|CRO|chief|head of)\b/i },
  { type: "funding_ma",    strength: 0.8,  re: /\b(raises?|funding|series [a-e]|acquires?|acquisition|merger)\b/i },
  { type: "ai_rollout",    strength: 0.9,  re: /\b(rolls? out|deploys?|launch(es)?|pilot(s)?|adopts?)\b.*\b(AI|copilot|agent|GenAI|LLM)\b/i },
  { type: "hiring",        strength: 0.75, re: /\b(hiring|vacanc|job opening|recruit)\b/i },
  { type: "breach_incident", strength: 0.85, re: /\b(breach|cyber ?attack|incident|ransomware|outage)\b/i },
  { type: "regulation",    strength: 0.5,  re: /\b(AI Act|DORA|NIS2|GDPR|regulat|fine[sd]?)\b/i },
];

const now = Date.now();

const out = [];
const input = $input.all();
for (let i = 0; i < input.length; i++) {
  const item = input[i];
  const a = item.json;
  if (!a.title) continue;                       // failed feed or empty item
  const text = `${a.title} ${a.contentSnippet || ""}`;

  const trig = TRIGGERS.find(t => t.re.test(text));
  if (!trig) continue;                           // news, but not a trigger

  const published = new Date(a.isoDate || a.pubDate || now).getTime();
  const ageDays = Math.max(0, Math.round((now - published) / 86400000));
  if (ageDays > MAX_AGE_DAYS) continue;          // context, not a trigger

  const decay = Math.pow(0.5, ageDays / HALF_LIFE_DAYS);
  // Which watchlist query produced this article? Follow n8n's item linking back to the Watchlist node.
  let watch = "unknown";
  try { watch = $('Watchlist').itemMatching(i).json.watch; } catch (e) {}

  // Google News titles end with " - Source name". The source is secondary until a human checks the primary source.
  const source = (a.title.match(/ - ([^-]+)$/) || [])[1] || "unknown";

  out.push({
    json: {
      watch,
      trigger: trig.type,
      title: a.title,
      story: a.title.replace(/ - [^-]+$/, "").toLowerCase().replace(/[^a-z0-9 ]/g, "").split(" ").slice(0, 4).join(" "),
      link: a.link,
      source,
      published: new Date(published).toISOString().slice(0, 10),
      age_days: ageDays,
      score: Math.round(trig.strength * decay * 100),
      verification: "secondary (news): check the primary source before using in outreach",
    },
  });
}
return out;

// Remove duplicates within this run AND across runs, then keep the best signals.
// Cross-run memory uses workflow static data. It is only used on scheduled runs,
// so manual test runs always show the full result.
const MIN_SCORE = 30;
const TOP_N = 15;

const scheduled = $execution.mode === 'trigger';
const memory = scheduled ? $getWorkflowStaticData('global') : {};
memory.seen = memory.seen || {};

// Highest score first, so when the same story appears in several outlets we keep the best one.
const sorted = $input.all().sort((a, b) => b.json.score - a.json.score);
const seenNow = new Set();
const fresh = [];
for (const item of sorted) {
  const key = item.json.link || item.json.title;
  const story = item.json.story;            // same story, different outlet
  if (seenNow.has(key) || seenNow.has(story) || memory.seen[key]) continue;
  seenNow.add(key); seenNow.add(story);
  if (item.json.score < MIN_SCORE) continue;
  fresh.push(item);
}

// Remember what we reported, and forget entries older than 120 days.
const today = new Date().toISOString().slice(0, 10);
for (const i of fresh) memory.seen[i.json.link || i.json.title] = today;
const cutoff = new Date(Date.now() - 120 * 86400000).toISOString().slice(0, 10);
for (const [k, d] of Object.entries(memory.seen)) if (d < cutoff) delete memory.seen[k];

return fresh
  .sort((a, b) => b.json.score - a.json.score)
  .slice(0, TOP_N);

// Build a daily digest in Markdown and HTML (one output item).
const items = $input.all().map(i => i.json);
const date = new Date().toISOString().slice(0, 10);

if (items.length === 0) {
  return [{ json: { date, count: 0, markdown: `# Signal digest ${date}\n\nNo new signals above the threshold today.`, html: `<h2>Signal digest ${date}</h2><p>No new signals above the threshold today.</p>` } }];
}

const md = [
  `# Signal digest ${date}`,
  ``,
  `${items.length} new signal(s). All come from news coverage: **verify the primary source before using one in outreach.**`,
  ``,
  `| Score | Watch | Trigger | Age | Headline |`,
  `|---:|---|---|---:|---|`,
  ...items.map(s => `| ${s.score} | ${s.watch} | ${s.trigger} | ${s.age_days}d | [${s.title.replace(/\|/g, "/")}](${s.link}) |`),
].join("\n");

const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
const html = `<h2>Signal digest ${date}</h2>
<p>${items.length} new signal(s). Verify the primary source before using one in outreach.</p>
<table border="1" cellpadding="6" cellspacing="0">
<tr><th>Score</th><th>Watch</th><th>Trigger</th><th>Age</th><th>Headline</th></tr>
${items.map(s => `<tr><td>${s.score}</td><td>${esc(s.watch)}</td><td>${s.trigger}</td><td>${s.age_days}d</td><td><a href="${esc(s.link)}">${esc(s.title)}</a></td></tr>`).join("\n")}
</table>`;

return [{ json: { date, count: items.length, markdown: md, html } }];
